input.sparql:
PREFIX brick: <https://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://xi.li.org/util/ref#>
SELECT ?x ?class ?id WHERE {
  ?x a brick:ElectricalSensor .
  ?x ref:hasTimeseriesId ?id .
}

PREFIX brick: <https://brickschema.org/schema/1.2/brick#>
PREFIX ref: <http://xi.li.org/util/ref#>
SELECT DISTINCT ?pred WHERE { ?x ?pred ?y }

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?x ?class WHERE {
  ?x a ?class .
  FILTER( STRSTARTS(STR(?class), "https://brickschema.org/schema/Brick#Elec") )
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?tsref WHERE {
  ?sensor ref:hasExternalReference ?e .
  ?e ref:hasTimeseriesId ?tsref .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?sensor ?cls ?point ?tsref WHERE {
  ?sensor ref:hasExternalReference ?e .
  ?e ref:hasTimeseriesId ?tsref .
  ?sensor a ?cls .
  FILTER (CONTAINS(STR(?sensor), "Electric_Power_Sensor") || ?sensor = "http://buildgraph.org/BG_small_office_2004_0000#ElectricMeter")
  OPTIONAL { ?sensor brick:isPointOf ?point }
}
